  return (
    Math.sin(x * 0.7 + t * 0.6) * 0.5 +
    Math.sin(y * 0.9 - t * 0.4) * 0.3 +
    Math.sin((x + y) * 0.5 + t * 0.8) * 0.2
  );
};

